-- Operational checks must all be zero. Run the legacy-review query separately.
with recursive chain as(select id,replaced_by_invoice_id,array[id] path,false cycle from public.invoices where replaced_by_invoice_id is not null union all select c.id,i.replaced_by_invoice_id,c.path||i.id,i.id=any(c.path) from chain c join public.invoices i on i.id=c.replaced_by_invoice_id where not c.cycle)
select 'multiple_active_invoices' check_name,count(*) violations from(select billing_record_id from public.invoice_billing_records where is_active group by billing_record_id having count(*)>1) d
union all select 'inactive_document_active_link',count(*) from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id where x.is_active and (i.status<>'ACTIVE' or i.voided_at is not null)
union all select 'issued_request_inactive_invoice',count(*) from public.invoice_requests r join public.invoices i on i.id=r.invoice_id where r.status='ISSUED' and (i.status<>'ACTIVE' or i.voided_at is not null)
union all select 'pending_request_active_invoice',count(*) from public.invoice_requests r join public.invoice_billing_records x on x.billing_record_id=r.billing_record_id where r.status='PENDING' and x.is_active
union all select 'request_payment_mismatch',count(*) from public.invoice_requests r join public.billing_records b on b.id=r.billing_record_id where r.status in ('PENDING','ISSUED') and (b.payment_status<>'PAGO' or b.billing_method<>'PARTICULAR' or b.received_amount is distinct from r.received_amount_snapshot or b.paid_at is distinct from r.paid_at_snapshot or b.billing_entity_id<>r.billing_entity_id)
union all select 'insurance_paid_without_active_paid_invoice',count(*) from public.billing_records b where b.billing_method='CONVENIO' and b.settlement_mode='INVOICE' and b.payment_status='PAGO' and not exists(select 1 from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id where x.billing_record_id=b.id and x.is_active and i.paid_at is not null)
union all select 'verified_allocation_mismatch',count(*) from public.invoices i where i.status='ACTIVE' and i.voided_at is null and i.recipient_type='CONVENIO' and i.allocation_verified and (i.net_amount is distinct from (select sum(x.received_amount) from public.invoice_billing_records x where x.invoice_id=i.id)+i.closing_adjustment or exists(select 1 from public.invoice_billing_records x where x.invoice_id=i.id and x.received_amount is null))
union all select 'verified_private_parts_mismatch',count(*) from public.billing_records b where b.billing_method='PARTICULAR' and b.payment_status='PAGO' and b.payment_composition_verified and b.received_amount is distinct from (select sum(p.amount) from public.payment_parts p where p.billing_record_id=b.id)
union all select 'verified_insurance_parts_mismatch',count(*) from public.invoices i where i.recipient_type='CONVENIO' and i.status='ACTIVE' and i.voided_at is null and i.paid_at is not null and i.payment_composition_verified and i.net_amount is distinct from (select sum(p.amount) from public.payment_parts p where p.invoice_id=i.id)
union all select 'cancelled_attendance_active_invoice',count(*) from public.attendances a join public.billing_records b on b.attendance_id=a.id join public.invoice_billing_records x on x.billing_record_id=b.id where a.status='cancelled' and x.is_active
union all select 'orphan_invoice_item',count(*) from public.invoice_billing_records x left join public.invoices i on i.id=x.invoice_id left join public.billing_records b on b.id=x.billing_record_id where i.id is null or b.id is null
union all select 'replacement_cycle',count(*) from chain where cycle
union all select 'private_invoice_cardinality',count(*) from public.invoices i where i.recipient_type='PARTICULAR' and (select count(*) from public.invoice_billing_records x where x.invoice_id=i.id)<>1;

-- Explicit legacy exceptions. No inferred allocation or fictional payment methods.
select (select count(*) from public.invoices where recipient_type='CONVENIO' and not allocation_verified) legacy_allocation_review,
 (select count(*) from public.invoices where recipient_type='CONVENIO' and paid_at is not null and not payment_composition_verified) legacy_invoice_composition_review,
 (select count(*) from public.billing_records where billing_method='PARTICULAR' and payment_status='PAGO' and not payment_composition_verified) legacy_private_composition_review;
